INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 3873, 'តារាងប្រូបាបនៃចំនួនរថយន្តលក់បានក្នុងមួយថ្ងៃ \(x = 0,1,2,3\) ៖ \(P(0)=0.15, P(1)=0.35, P(2)=?, P(3)=0.20\)។ ក. រក \(P(2)\)។ ខ. រកប្រូបាបលក់បានយ៉ាងតិច \(2\) គ្រឿង។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. ផលបូក \(= 1\) ⇒ \(P(2) = 1 - 0.15 - 0.35 - 0.20 = 0.30\) (3 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 3874, 'ក្នុងក្រុមហ៊ុនមួយ គ្រួសារ \(30\) មានកូន \(1\) នាក់ \(43\) មានកូន \(2\) នាក់ \(10\) មានកូន \(3\) នាក់ និង \(4\) មានកូនលើស \(3\) នាក់ (គ្រួសារមួយចំនួនគ្មានកូន)។ សរុបមាន \(100\) គ្រួសារ។ ក. រកចំនួនគ្រួសារគ្មានកូន។ ខ. រកប្រូបាបជ្រើសបានគ្រួសារមានកូនយ៉ាងតិច \(2\) នាក់។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(100 - (30+43+10+4) = 13\) គ្រួសារ (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 3875, 'សិស្ស \(200\) នាក់ ក្នុងនោះ \(80\) នាក់ជិះកង់ \(50\) នាក់ជិះម៉ូតូ ហើយនៅសល់ដើរ។ ជ្រើសសិស្សម្នាក់ដោយចៃដន្យ។ ក. ប្រូបាបជិះកង់។ ខ. ប្រូបាបជិះម៉ូតូ។ គ. ប្រូបាបដើរ។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(\dfrac{80}{200} = 40\%\) (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 3876, 'ថាសបង្វិលមួយចែក \(8\) ផ្នែកស្មើគ្នា លេខ \(1\) ដល់ \(8\)។ ក. ប្រូបាបបានលេខសេស។ ខ. ប្រូបាបបានលេខធំជាង \(6\)។ គ. ប្រូបាបបានលេខ \(9\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(\dfrac{4}{8} = \dfrac{1}{2}\) (1 ពិន្ទុ)
